mapper.update:
update orient_score_recovery set status=1,reference_id=#{referenceId},resolution_note=#{resolutionNote},
       handled_by=#{handledBy},handled_at=#{handledAt}
 where id=#{id} and status=0

mapper.select:
select count(*) from orient_task_attempt
 where member_id = #{memberId} and activity_id = #{activityId} and topic_id = #{topicId}
   and play_instance_id = #{playInstanceId} and status = 0 and alternative_task_type = 'PHOTO'

select distinct task_id from orient_task_completion
 where member_id = #{memberId} and activity_id = #{activityId} and topic_id = #{topicId}
   and play_instance_id = #{playInstanceId}
 order by task_id

select count(*) from player_node_progress
 where member_id = #{memberId} and activity_id = #{activityId} and topic_id = #{topicId}
   and play_instance_id = #{playInstanceId} and status = 1 and review_status = 0 and del_flag = 0

select  from orient_score_appeal
 status = #{status}
 order by id desc limit #{limit}

select count(*) from orient_score_appeal
 where session_id = #{sessionId} and status = 0

       and entry_id = #{entryId}
       and entry_id is null and node_id = #{nodeId}

select  from orient_result_dispute
 status = #{status}
 order by id desc limit #{limit}
